pub fn safe_fields(fields: &[(&str, &str)]) -> Vec<(String, String)> {
    fields
        .iter()
        .map(|(k, v)| {
            let sensitive = [
                "authorization",
                "cookie",
                "password",
                "token",
                "api_key",
            ]
            .contains(&k.to_ascii_lowercase().as_str());
            (
                k.to_string(),
                if sensitive {
                    "[REDACTED]".to_owned()
                } else {
                    v.to_string()
                },
            )
        })
        .collect()
}

fn main() {
    assert_eq!(
        safe_fields(&[
            ("Authorization", "bearer x"),
            ("request_id", "r1")
        ]),
        vec![
            ("Authorization".to_owned(), "[REDACTED]".to_owned()),
            ("request_id".to_owned(), "r1".to_owned())
        ],
        "case 1"
    );
    assert_eq!(safe_fields(&[]), vec![], "case 2");
    assert_eq!(
        safe_fields(&[("TOKEN", "x"), ("api_key", "y")]),
        vec![
            ("TOKEN".to_owned(), "[REDACTED]".to_owned()),
            ("api_key".to_owned(), "[REDACTED]".to_owned())
        ],
        "case 3"
    );
    assert_eq!(
        safe_fields(&[("operation", "list")]),
        vec![("operation".to_owned(), "list".to_owned())],
        "case 4"
    );
    println!("worked example passed");
}

